#include <bits/stdc++.h>
using namespace std;
#define ll long long int 


void solve() {
    int n; cin>>n;
    vector<int> a(3*n);
    for(int i=0; i<3*n; i++) cin>>a[i];
    sort(a.rbegin(),a.rend());
    
    int l = 0, r = 3*n-1;
    long long ans = 0;
    
    int x,y,z;
    while(l<r) {
        // x only case
        x = a[l], y = a[r-1], z = a[r];
        if(x>=2*y && x>=y+z) {
            ans += 6*x;
            l++;
            r-=2;
            continue;
        }
        
        // x+y
        x = a[l], y = a[l+1], z = a[r];
        if(2*y>=x && y>=3*z-x) {
            ans += 4*x;
            ans += 4*y;
            l+=2;
            r--;
            continue;
        }
        else {
            ans += 3*x;
            ans += 3*y;
            ans += 3*z;
            l+=2;
            r--;
        }
    }
    
    cout<<ans<<endl;
}


ll check(vector<ll>&a, vector<ll>& pref, ll x, ll y, ll n){
    ll ans=2*pref[x]+pref[x+2*y]+3*pref[3*n-2*x-y];
    return ans;
}

void solve1(){
    ll n;
    cin>>n;
    vector<ll>a(3*n),pref(3*n+1);
    for(int i=0;i<3*n;i++){
        cin>>a[i];
    }
    sort(a.rbegin(),a.rend());
    for(int i=0;i<3*n;i++){
        pref[i+1]=pref[i]+a[i];
    }
    ll count=0;
    for(ll i=0;i<=n;i++){
        ll low=0,high=n-i;
        while(low<high){
            ll mid=(low+high)/2;
            if(check(a,pref,i,mid+1,n)>check(a,pref,i,mid,n)){
                low=mid+1;
            }
            else{
                high=mid;
            }
        }
        count=max(count,check(a,pref,i,low,n));
    }
    cout<<count<<endl;
}


int main() {
    int t; cin>>t;
    while(t--) solve1();
    
    return 0;

}
